import{_ as a,o as d,c as e,a2 as s}from"./chunks/framework.DGvnA5EY.js";const o="/workbuddy-guide/assets/01-office-trio.C3DeqUsW.png",b=JSON.parse('{"title":"第 11 章 办公三件套：Word、Excel、PPT","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 办公三件套是多数人第一次感受到 WorkBuddy 价值的地方。但很多人第一次用就失望： \\"它写得太模板了\\"\\"数字对不上\\"\\"PPT 丑\\"。根因通常不是模型不会写，而是你没把 交付标准说清楚…","frontmatter":{"title":"第 11 章 办公三件套：Word、Excel、PPT"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md","lastUpdated":1791615980000}'),n={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 办公三件套：Word、Excel、PPT/index.md"};function l(r,t,i,p,c,h){return d(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="第-11-章-办公三件套-word、excel、ppt" tabindex="-1">第 11 章 办公三件套：Word、Excel、PPT <a class="header-anchor" href="#第-11-章-办公三件套-word、excel、ppt" aria-label="Permalink to &quot;第 11 章 办公三件套：Word、Excel、PPT&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>办公三件套是多数人第一次感受到 WorkBuddy 价值的地方。但很多人第一次用就失望： &quot;它写得太模板了&quot;&quot;数字对不上&quot;&quot;PPT 丑&quot;。<strong>根因通常不是模型不会写，而是你没把 交付标准说清楚</strong>，或者没选对技能、没走对流程。</p><p>这一章带你把三类最常见的办公产物——Word 文档、Excel 表格、PPT 汇报——跑通到 &quot;能直接交出去&quot;的程度，并顺手把&quot;团建策划&quot;这类重复活固化成你自己的零成本技能。</p><p><img src="'+o+`" alt="一只小黑左手举着文档、右手举着表格和幻灯片，像端着办公三件套" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;办公三件套&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这次办公任务要交付什么" tabindex="-1">一、先想清楚：这次办公任务要交付什么 <a class="header-anchor" href="#一、先想清楚-这次办公任务要交付什么" aria-label="Permalink to &quot;一、先想清楚：这次办公任务要交付什么&quot;">​</a></h2><p>动手前用五问定标（详见本篇导读）给任务定标。很多&quot;AI 做得不好&quot;的办公任务， 卡在没说清下面这张表：</p><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>这份材料帮谁做什么决定</td><td>给部门负责人看，判断项目是否继续投入</td></tr><tr><td>受众</td><td>阅读者是谁、懂不懂背景</td><td>管理层只看结论；项目组需要过程和责任人</td></tr><tr><td>材料</td><td>哪些是事实来源、哪些只是参考</td><td><code>data.xlsx</code> 是唯一数据口径，旧版 PPT 只参考结构</td></tr><tr><td>格式</td><td>要 Word、Excel、PPT，还是三者联动</td><td>一份复盘 Word + 一张风险台账 Excel + 8 页汇报 PPT</td></tr><tr><td>验收</td><td>怎么判断结果可用</td><td>数字能回源、公式可刷新、PPT 投屏不溢出</td></tr></tbody></table><h2 id="二、先选对-skill-办公任务的推荐组合" tabindex="-1">二、先选对 Skill：办公任务的推荐组合 <a class="header-anchor" href="#二、先选对-skill-办公任务的推荐组合" aria-label="Permalink to &quot;二、先选对 Skill：办公任务的推荐组合&quot;">​</a></h2><p>SkillHub 上有大量办公、文档、表格、PPT、会议纪要相关技能。先认准官方源安装， 再按场景挑。一个实用搭配思路：<strong>本地文件优先 Word/DOCX、Excel/XLSX、 Powerpoint/PPTX；在线协作用腾讯文档或 kdocs；材料多时先 Markdown Converter 抽取结构；会议类叠加腾讯会议或纪要类技能。</strong></p><table tabindex="0"><thead><tr><th>Skill 名称</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>Word / DOCX</strong></td><td>Word 文档</td><td>新建、检查、编辑 docx，处理标题、编号、表格、修订记录</td><td>适合本地 docx 文件</td></tr><tr><td><strong>Excel / XLSX</strong></td><td>Excel 表格</td><td>读取、清洗、写入工作簿，处理公式、日期、格式、模板保留</td><td>先确认数据口径</td></tr><tr><td><strong>Powerpoint / PPTX</strong></td><td>PPT 文件</td><td>创建、编辑、检查 pptx，处理版式、占位符、备注、图表、视觉质检</td><td>生成后仍要人工审稿</td></tr><tr><td><strong>Office Document Specialist Suite</strong></td><td>Word/Excel/PPT 综合</td><td>综合处理 Office 文件，适合自动化报告和多文件联动</td><td>复杂任务建议分步验收</td></tr><tr><td><strong>wps</strong></td><td>WPS 三件套</td><td>面向中国用户的 WPS 文字、表格、演示工作流</td><td>适合 WPS 生态用户</td></tr><tr><td><strong>腾讯文档 TENCENT DOCS</strong></td><td>在线协作</td><td>创建、读取、编辑、搜索腾讯文档（在线 Word/Excel/幻灯片）</td><td>通常需要授权</td></tr><tr><td><strong>kdocs skill</strong></td><td>金山/WPS 云文档</td><td>处理 WPS 云文档、智能文档、表格、PPT、PDF、知识库</td><td>通常需要 API Key</td></tr><tr><td><strong>Markdown Converter</strong></td><td>材料解析</td><td>把 PDF/Word/PPT/Excel 转成 Markdown，让模型先理解内容</td><td>适合读材料，不等于最终排版</td></tr><tr><td><strong>PPT Generator / PPT Workflow</strong></td><td>PPT 生成</td><td>从主题、讲稿或材料自动生成演示稿，适合初稿和结构化汇报</td><td>生成后仍需审稿</td></tr><tr><td><strong>Excel 公式生成</strong></td><td>公式问题</td><td>把自然语言转成 Excel/WPS/Google Sheets 公式并解释防错版本</td><td>公式要在样例数据上验证</td></tr><tr><td><strong>腾讯会议</strong></td><td>会议到文档</td><td>预约会议、取转写、取 AI 纪要，再转 Word 纪要/Excel 待办/PPT 汇报</td><td>需要会议平台授权</td></tr></tbody></table><blockquote><p><strong>零成本 Skill 入口</strong>：不知道装哪个，先装 <code>find-skills</code>，告诉它&quot;我每周做团建 策划、周报、数据透视&quot;，它帮你配装；跑顺的活再用 <code>skill-creator</code> 固化成专属技能 （见本章第五节）。</p></blockquote><h2 id="三、word-从空白页到可提交的文档" tabindex="-1">三、Word：从空白页到可提交的文档 <a class="header-anchor" href="#三、word-从空白页到可提交的文档" aria-label="Permalink to &quot;三、Word：从空白页到可提交的文档&quot;">​</a></h2><h3 id="这个场景的痛点" tabindex="-1">这个场景的痛点 <a class="header-anchor" href="#这个场景的痛点" aria-label="Permalink to &quot;这个场景的痛点&quot;">​</a></h3><p>Word 看起来只是写字，但真实办公里的难点通常有四个：<strong>不知道按什么结构写、 语气不够正式、标题和编号混乱、内容没有证据来源</strong>。尤其是方案、通知、报告、纪要、 制度、申请、PRD 这类文档，如果开头就让 AI 自由发挥，结果往往像&quot;万能模板&quot;—— 读起来完整，却很难直接提交。</p><p>WorkBuddy 适合解决的不是&quot;替你拍脑袋&quot;，而是<strong>把已有材料变成结构稳定、语气一致、 可以继续修改的文档初稿</strong>。把目标、提交对象、语气和结构一次说清，生成后再用 &quot;差异反馈&quot;继续改，而不是每次从头生成。</p><h3 id="适合交给-word-的任务" tabindex="-1">适合交给 Word 的任务 <a class="header-anchor" href="#适合交给-word-的任务" aria-label="Permalink to &quot;适合交给 Word 的任务&quot;">​</a></h3><ul><li><strong>正式方案</strong>：活动策划、项目方案、营销方案、培训方案</li><li><strong>管理文档</strong>：制度、通知、申请、会议纪要、复盘报告、周报月报</li><li><strong>产品材料</strong>：PRD、需求说明、竞品分析、用户访谈总结</li></ul><h3 id="推荐流程" tabindex="-1">推荐流程 <a class="header-anchor" href="#推荐流程" aria-label="Permalink to &quot;推荐流程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>读取材料，列出可用信息和缺失项</td><td>哪些材料是事实来源，哪些只是参考</td></tr><tr><td>2</td><td>生成文档大纲和写作口径</td><td>读者是谁，文档是汇报、审批还是执行</td></tr><tr><td>3</td><td>按大纲生成 Word 初稿</td><td>标题层级、章节顺序、关键信息是否完整</td></tr><tr><td>4</td><td>根据反馈润色、补充、删减</td><td>哪些可定稿，哪些必须标&quot;待确认&quot;</td></tr><tr><td>5</td><td>输出可编辑 docx 和修改说明</td><td>是否能直接发给同事审阅</td></tr></tbody></table><h3 id="提示词-1-生成一份团建活动策划-word-框架" tabindex="-1">提示词 1｜生成一份团建活动策划 Word 框架 <a class="header-anchor" href="#提示词-1-生成一份团建活动策划-word-框架" aria-label="Permalink to &quot;提示词 1｜生成一份团建活动策划 Word 框架&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我生成一份公司团建活动策划的 Word 文档框架。</span></span>
<span class="line"><span>公司约 80 人，包含：活动目标、活动主题建议、整体流程安排（含时间节点）、</span></span>
<span class="line"><span>分组与互动游戏建议、预算构成清单、人员分工、风险预案和注意事项。</span></span>
<span class="line"><span>语言简洁实用，不需要写得过于详细，重点把整体框架和关键决策项列清楚，</span></span>
<span class="line"><span>适合直接拿去和领导确认活动方向。</span></span></code></pre></div><h3 id="提示词-2-二次修改不要重写-要说差异" tabindex="-1">提示词 2｜二次修改不要重写，要说差异 <a class="header-anchor" href="#提示词-2-二次修改不要重写-要说差异" aria-label="Permalink to &quot;提示词 2｜二次修改不要重写，要说差异&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请在上一版公司团建活动策划 Word 文档基础上进行修改，不要重新生成整篇。</span></span>
<span class="line"><span>修改要求：</span></span>
<span class="line"><span>将活动目标压缩为 3 条，每条不超过 50 字；</span></span>
<span class="line"><span>将流程安排改成表格，列为：时间、环节、主要内容、负责人、所需物料；</span></span>
<span class="line"><span>在节目类型建议中增加适合 100 人规模公司的互动环节，并删除执行难度过高的方案；</span></span>
<span class="line"><span>将预算构成进一步细化，增加：预算项目、预计金额、数量、单价、备注，并补充预算总额；</span></span>
<span class="line"><span>新增风险预案部分，覆盖人员迟到、设备故障、节目超时和突发安全问题；</span></span>
<span class="line"><span>整体语言更加正式、简洁，适合直接提交给领导审批。</span></span>
<span class="line"><span>输出修改后的 v2 版 Word 文档，并在 changelog.md 中列出本次修改内容。</span></span></code></pre></div><h3 id="提示词-3-比较两版制度-合同-方案" tabindex="-1">提示词 3｜比较两版制度 / 合同 / 方案 <a class="header-anchor" href="#提示词-3-比较两版制度-合同-方案" aria-label="Permalink to &quot;提示词 3｜比较两版制度 / 合同 / 方案&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>比较 policy-v3.docx 与 policy-v4.docx。</span></span>
<span class="line"><span>输出新增、删除、修改和仅格式变化四类差异，附章节和原文定位。</span></span>
<span class="line"><span>重点标记金额、日期、责任主体、审批条件、例外和否定表达。</span></span>
<span class="line"><span>生成影响清单和待确认问题，不给法律结论，不修改原文件。</span></span></code></pre></div><blockquote><p>文档对比适合发现变化，不替代法务、财务或制度责任人的最终判断。</p></blockquote><h2 id="四、excel-把表格变成能回答问题的分析" tabindex="-1">四、Excel：把表格变成能回答问题的分析 <a class="header-anchor" href="#四、excel-把表格变成能回答问题的分析" aria-label="Permalink to &quot;四、Excel：把表格变成能回答问题的分析&quot;">​</a></h2><h3 id="这个场景的痛点-1" tabindex="-1">这个场景的痛点 <a class="header-anchor" href="#这个场景的痛点-1" aria-label="Permalink to &quot;这个场景的痛点&quot;">​</a></h3><p>Excel 的问题通常不在&quot;会不会做图&quot;，而在&quot;这个表到底能回答什么问题&quot;。很多人 让 AI 做表，结果拿到一张漂亮但口径错的表。关键有两步：<strong>先定口径，再让 AI 填</strong>。</p><h3 id="提示词-1-销售数据清洗-透视" tabindex="-1">提示词 1｜销售数据清洗 + 透视 <a class="header-anchor" href="#提示词-1-销售数据清洗-透视" aria-label="Permalink to &quot;提示词 1｜销售数据清洗 + 透视&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把这份销售表删掉重复行，统一日期格式为 YYYY-MM-DD，</span></span>
<span class="line"><span>按地区汇总销售额，生成透视表，并标记销售额同比下降超过 20% 的地区。</span></span>
<span class="line"><span>数据口径以【data.xlsx】的&quot;实收金额&quot;列为准，不要用&quot;预估&quot;列。</span></span>
<span class="line"><span>输出新的 xlsx，保留原表作为&quot;原始数据&quot;分页。</span></span></code></pre></div><h3 id="提示词-2-自然语言转公式-再用-excel-公式生成技能复核" tabindex="-1">提示词 2｜自然语言转公式（再用 Excel 公式生成技能复核） <a class="header-anchor" href="#提示词-2-自然语言转公式-再用-excel-公式生成技能复核" aria-label="Permalink to &quot;提示词 2｜自然语言转公式（再用 Excel 公式生成技能复核）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在【预算表.xlsx】的&quot;合计&quot;列写一条公式：</span></span>
<span class="line"><span>当&quot;类型&quot;为收入时，合计=金额；为支出时，合计=-金额。</span></span>
<span class="line"><span>并用 Excel 公式生成技能解释这条公式的防错写法（比如空值、文本混入怎么处理）。</span></span></code></pre></div><h3 id="执行步骤" tabindex="-1">执行步骤 <a class="header-anchor" href="#执行步骤" aria-label="Permalink to &quot;执行步骤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>读表、识别口径字段</td><td>哪一列是唯一数据口径，要不要去重</td></tr><tr><td>2</td><td>清洗、建公式、生成透视</td><td>公式逻辑是否符合你的算法</td></tr><tr><td>3</td><td>输出新 xlsx</td><td>抽样核对 3–5 行，数字能对上源</td></tr></tbody></table><h2 id="五、ppt-先有骨架-再有皮" tabindex="-1">五、PPT：先有骨架，再有皮 <a class="header-anchor" href="#五、ppt-先有骨架-再有皮" aria-label="Permalink to &quot;五、PPT：先有骨架，再有皮&quot;">​</a></h2><h3 id="这个场景的痛点-2" tabindex="-1">这个场景的痛点 <a class="header-anchor" href="#这个场景的痛点-2" aria-label="Permalink to &quot;这个场景的痛点&quot;">​</a></h3><p>做 PPT 最容易翻车的是&quot;一上来就要漂亮&quot;。正确顺序是<strong>先大纲、再内容、最后版式</strong>， 把&quot;定逻辑&quot;和&quot;做美化&quot;拆开，能少改好几遍。</p><h3 id="提示词-从主题生成-ppt-先大纲后扩写" tabindex="-1">提示词｜从主题生成 PPT（先大纲后扩写） <a class="header-anchor" href="#提示词-从主题生成-ppt-先大纲后扩写" aria-label="Permalink to &quot;提示词｜从主题生成 PPT（先大纲后扩写）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先给我这份【产品介绍】PPT 的 12 页大纲，每页一句话主题和 3 个要点，不要做版式。</span></span>
<span class="line"><span>我看完大纲确认逻辑后，再让你扩写成完整内容并套用商务蓝配色。</span></span>
<span class="line"><span>重点页：第 1 页痛点、第 4 页核心功能、第 9 页价格方案、第 12 页行动号召。</span></span></code></pre></div><h3 id="执行步骤-1" tabindex="-1">执行步骤 <a class="header-anchor" href="#执行步骤-1" aria-label="Permalink to &quot;执行步骤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>出大纲（标题 + 要点）</td><td>叙事逻辑、重点页是否到位</td></tr><tr><td>2</td><td>你确认大纲后扩写内容</td><td>事实和数字是否准确</td></tr><tr><td>3</td><td>套版式、配图、质检</td><td>投屏不溢出、字体统一、无乱码</td></tr></tbody></table><blockquote><p>生成后仍要人工审稿：尤其是对外汇报，数字、引用、品牌名必须核对。</p></blockquote><h2 id="六、零成本-skill-把-团建策划-固化成你的专属技能" tabindex="-1">六、零成本 Skill：把&quot;团建策划&quot;固化成你的专属技能 <a class="header-anchor" href="#六、零成本-skill-把-团建策划-固化成你的专属技能" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;团建策划&quot;固化成你的专属技能&quot;">​</a></h2><p>跑顺上面提示词 1、2 之后，这类&quot;每周/每月都做&quot;的文档就可以固化成技能，下次 只说主题就出初稿。用 <code>skill-creator</code> 的自然语言方式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个&quot;团建策划&quot;技能。</span></span>
<span class="line"><span>用途：以后我直接说公司人数和偏好，它就能生成团建策划 Word 框架，</span></span>
<span class="line"><span>并支持按我的 v2 修改要求（压缩目标、流程改表格、细化预算、加风险预案）迭代。</span></span>
<span class="line"><span>触发词：团建、活动策划、team building。</span></span>
<span class="line"><span>输出格式：参考这一版已验证的策划结构。</span></span></code></pre></div><p>固化后，你在 SkillHub 里就有了一个&quot;只属于你公司&quot;的策划技能——这就是零成本： 不写代码、不花钱，把经验变成工具。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：你会拿到结构稳定、语气一致、可继续编辑的 <code>.docx</code> / <code>.xlsx</code> / <code>.pptx</code> 文件，而不是聊天里的一段文字。</p><p><strong>验收标准</strong>（怎样算做对了）：</p><ul><li>[ ] 数字能回到源文件（Excel 抽样 3–5 行对得上；Word/PPT 里的关键数字有出处）</li><li>[ ] Excel 公式可刷新、口径和你一致（不是&quot;看起来对&quot;）</li><li>[ ] PPT 投屏不溢出、字体统一、无乱码，逻辑经你确认</li><li>[ ] 对外文档已标&quot;待确认&quot;项，关键事实你已核对</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>.docx / .xlsx / .pptx</strong>：分别是 Word、Excel、PowerPoint 的文件格式，用对应软件打开就能继续编辑。</p><p><strong>大纲（Outline）</strong>：PPT 或长文的&quot;骨架&quot;——只列每部分讲什么，不做美化。先定骨架再填肉，改起来最省事。</p><p><strong>SkillHub</strong>：WorkBuddy 的技能市场，官方源经过安全过滤；装技能优先从这里装。</p><p><strong>零成本 Skill</strong>：用 <code>skill-creator</code> 把你的重复工作流固化成专属技能，不写代码、不花钱。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 用提示词 1 让 WorkBuddy 写一份你真正用得上的 Word 文档，并核对事实</li><li>[ ] 做一个 Excel 表，验证公式是否按你的口径计算</li><li>[ ] 用&quot;先大纲后版式&quot;的方法出一份 PPT 大纲并审一遍逻辑</li><li>[ ] （进阶）用 skill-creator 把其中一件重复活固化成你的专属技能</li></ul><hr><p><em>下一篇：第 12 章——从整理桌面文件这些小事做起，让电脑不再乱。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,61)])])}const q=a(n,[["render",l]]);export{b as __pageData,q as default};
